`, "",{"version":3,"sources":["webpack://./src/components/Editor/Resources/ResourceRoomType.vue"],"names":[],"mappings":";AAmEA;EACA,QAAA;AACA","sourcesContent":["<!--\n  - SPDX-FileCopyrightText: 2021 Nextcloud GmbH and Nextcloud contributors\n  - SPDX-License-Identifier: AGPL-3.0-or-later\n-->\n\n<template>\n\t<div class=\"resource-room-type\">\n\t\t<div class=\"resource-room-type__input\">\n\t\t\t<NcSelect :value=\"getOption(value)\"\n\t\t\t\t:options=\"options\"\n\t\t\t\t:placeholder=\"placeholder\"\n\t\t\t\t:clearable=\"false\"\n\t\t\t\t:label-outside=\"true\"\n\t\t\t\tinput-id=\"value\"\n\t\t\t\tlabel=\"label\"\n\t\t\t\t@option:selected=\"changeValue\">\n\t\t\t\t<template #option=\"option\">\n\t\t\t\t\t<div>{{ option.label !== null ? option.label : \"\" }}</div>\n\t\t\t\t</template>\n\t\t\t</NcSelect>\n\t\t</div>\n\t</div>\n</template>\n\n<script>\nimport { NcSelect } from '@nextcloud/vue'\nimport { getAllRoomTypes } from '../../../models/resourceProps.js'\n\nexport default {\n\tname: 'ResourceRoomType',\n\tcomponents: {\n\t\tNcSelect,\n\t},\n\tprops: {\n\t\tvalue: {\n\t\t\ttype: String,\n\t\t\trequired: true,\n\t\t},\n\t},\n\tcomputed: {\n\t\tplaceholder() {\n\t\t\treturn this.$t('calendar', 'Room type')\n\t\t},\n\t\toptions() {\n\t\t\treturn [\n\t\t\t\t{ value: '', label: this.$t('calendar', 'Any') },\n\t\t\t\t...getAllRoomTypes(),\n\t\t\t]\n\t\t},\n\t},\n\tmethods: {\n\t\tgetOption(value) {\n\t\t\t// Selecting 'Any' will reset the input\n\t\t\tif (value === '') {\n\t\t\t\treturn undefined\n\t\t\t}\n\n\t\t\treturn this.options.find(option => option.value === value)\n\t\t},\n\t\tchangeValue(option) {\n\t\t\tthis.$emit('update:value', option.value)\n\t\t},\n\t},\n}\n</script>\n\n<style scoped>\n:deep(#value) {\n  width: 0;\n}\n</style>\n"],"sourceRoot":""}]);
